/* Friendly names for the backend's OpenAPI schemas. api.gen.ts is generated by
   `npm run gen:api`; don't edit it. The spec types several enums as plain `string`,
   so the unions below narrow them to the values the backend actually sends. */
import type { components } from "./api.gen";

type Schemas = components["schemas"];

export type UserRole = Schemas["UserRole"];
export type UserStatus = Schemas["UserStatus"];
/** Lifecycle of an uploaded document in the processing pipeline. */
export type DocumentStatus = "queued" | "processed" | "failed";
export type AssignmentStatus = "open" | "closed";
export type LogLevel = "info" | "warning" | "error";
export type ServiceStatus = "running" | "stopped";
/** Status of a document's HTML rendering (not of its similarity check). */
export type PreviewStatus = "processing" | "processed" | "failed";

export type UserResponse = Schemas["UserResponse"];
export type CreateUserInput = Schemas["CreateUserInput"];
export type LoginInput = Schemas["LoginInput"];

export type AssignmentResponse = Omit<Schemas["AssignmentResponse"], "status"> & { status: AssignmentStatus };
export type CreateAssignmentInput = Schemas["CreateAssignmentInput"];
export type EnrolledStudentResponse = Schemas["EnrolledStudentResponse"];
export type EnrollInput = Schemas["EnrollInput"];
export type EnrollResponse = Schemas["EnrollResponse"];

export type DocumentResponse = Omit<Schemas["DocumentResponse"], "status"> & { status: DocumentStatus };
export type PersistDocumentsInput = Schemas["PersistDocumentsInput"];
export type PersistDocumentsResponse = Schemas["PersistDocumentsResponse"];

export type SubmissionResponse = Omit<Schemas["SubmissionResponse"], "documentStatus"> & { documentStatus: DocumentStatus };
export type CreateSubmissionInput = Schemas["CreateSubmissionInput"];
export type UpdateSimilarityThresholdInput = Schemas["UpdateSimilarityThresholdInput"];

export type DocumentChunk = Schemas["DocumentChunk"];
export type DocumentChunkResponse = Schemas["DocumentChunkResponse"];
export type SimilarDocument = Schemas["SimilarDocumentResponse"];
export type SimilarityReport = Omit<Schemas["DocumentSimilarityReportResponse"], "status"> & { status: DocumentStatus };
export type SubmissionDetail = Omit<Schemas["SubmissionDetailResponse"], "documentStatus" | "similarityReport"> & {
  documentStatus: DocumentStatus;
  similarityReport: SimilarityReport | null;
};
export type HtmlPreview = Omit<Schemas["DocumentHtmlPreviewResponse"], "status"> & { status: PreviewStatus };

export type SystemLog = Omit<Schemas["SystemLogResponse"], "level"> & { level: LogLevel };
export type SystemHealth = {
  databaseStatus: ServiceStatus;
  workerStatus: ServiceStatus;
  serverStatus: ServiceStatus;
};

export type StudentDashboard = Omit<Schemas["StudentDashboardResponse"], "upcomingAssignments" | "submissionHistory"> & {
  upcomingAssignments: AssignmentResponse[];
  submissionHistory: SubmissionResponse[];
};
export type InstructorDashboard = Omit<Schemas["InstructorDashboardResponse"], "recentSubmissions"> & {
  recentSubmissions: SubmissionResponse[];
};
export type AdminDashboard = Omit<Schemas["AdminDashboardResponse"], "systemHealth" | "recentActivity"> & {
  systemHealth: SystemHealth;
  recentActivity: SystemLog[];
};
export type Dashboard = StudentDashboard | InstructorDashboard | AdminDashboard;
